query:
// Returning list of maps to satisfy MCP ingestion expectations.
MATCH (anchor:Memory {id: 'perf_mem_001'})<-[:SIMILAR_TO]-(candidate:Memory)
WHERE candidate.id <> anchor.id
RETURN {similar_id: candidate.id, memory_type: candidate.type, score: candidate.relevance_score}
ORDER BY candidate.relevance_score DESC
LIMIT 25
